// ipcam_soc_tb_top -- generated by socgen from socgen/specs/ipcam_soc.yaml
//   m_if[NM]  master ports: VIP masters drive them

//   s_if[NS]  NoC slave ports: memory VIPs, the APB subsystem (S_PERIPH)

//   the NoC between them is the env's behavioural ipcam_soc_noc component
// ============================================================================
`timescale 1ns/1ps
module ipcam_soc_tb_top;
  import uvm_pkg::*;
  `include "uvm_macros.svh"
  import ipcam_soc_pkg::*;
  import ipcam_soc_test_pkg::*;

  logic aclk = 1'b0;
  logic aresetn = 1'b0;
  always #(1.0) aclk = ~aclk;
  initial begin
    repeat (10) @(posedge aclk);
    aresetn <= 1'b1;
  end

  axi4_if m_if [NM] (.aclk(aclk), .aresetn(aresetn));
  axi4_if s_if [NS] (.aclk(aclk), .aresetn(aresetn));
  apb_if  apb_apb_ext_if (.pclk(aclk), .presetn(aresetn));
  apb_if  apb_venc_cfg_if (.pclk(aclk), .presetn(aresetn));
  apb_if  apb_jpeg_cfg_if (.pclk(aclk), .presetn(aresetn));
  apb_if  apb_npu_cfg_if (.pclk(aclk), .presetn(aresetn));

  for (genvar i = 0; i < NM; i++) begin : g_m
    axi4_sva #(.NAME($sformatf("m_%0d", i))) u_sva (m_if[i]);
    initial begin
      uvm_config_db#(virtual axi4_if)::set(null, $sformatf("uvm_test_top.env.m_%s.*", M_NAME[i]), "vif", m_if[i]);
      uvm_config_db#(virtual axi4_if)::set(null, "uvm_test_top.env.noc", $sformatf("m_vif_%0d", i), m_if[i]);
    end
  end
  for (genvar i = 0; i < NS; i++) begin : g_s
    axi4_sva #(.NAME($sformatf("s_%0d", i))) u_sva (s_if[i]);
    initial begin
      uvm_config_db#(virtual axi4_if)::set(null, $sformatf("uvm_test_top.env.s_%s.*", S_NAME[i]), "vif", s_if[i]);
      uvm_config_db#(virtual axi4_if)::set(null, "uvm_test_top.env.noc", $sformatf("s_vif_%0d", i), s_if[i]);
    end
  end

  // ---------------- APB subsystem on S_PERIPH ----------------

  logic [27:0] apb_irq;
  ipcam_soc_apb_subsys u_apb (
    .clk(aclk), .rst_n(aresetn),
    .awid(s_if[S_PERIPH].awid),
    .awaddr(s_if[S_PERIPH].awaddr),
    .awlen(s_if[S_PERIPH].awlen),
    .awsize(s_if[S_PERIPH].awsize),
    .awburst(s_if[S_PERIPH].awburst),
    .awprot(s_if[S_PERIPH].awprot),
    .awvalid(s_if[S_PERIPH].awvalid),
    .awready(s_if[S_PERIPH].awready),
    .wdata(s_if[S_PERIPH].wdata),
    .wstrb(s_if[S_PERIPH].wstrb),
    .wlast(s_if[S_PERIPH].wlast),
    .wvalid(s_if[S_PERIPH].wvalid),
    .wready(s_if[S_PERIPH].wready),
    .bid(s_if[S_PERIPH].bid),
    .bresp(s_if[S_PERIPH].bresp),
    .bvalid(s_if[S_PERIPH].bvalid),
    .bready(s_if[S_PERIPH].bready),
    .arid(s_if[S_PERIPH].arid),
    .araddr(s_if[S_PERIPH].araddr),
    .arlen(s_if[S_PERIPH].arlen),
    .arsize(s_if[S_PERIPH].arsize),
    .arburst(s_if[S_PERIPH].arburst),
    .arprot(s_if[S_PERIPH].arprot),
    .arvalid(s_if[S_PERIPH].arvalid),
    .arready(s_if[S_PERIPH].arready),
    .rid(s_if[S_PERIPH].rid),
    .rdata(s_if[S_PERIPH].rdata),
    .rresp(s_if[S_PERIPH].rresp),
    .rlast(s_if[S_PERIPH].rlast),
    .rvalid(s_if[S_PERIPH].rvalid),
    .rready(s_if[S_PERIPH].rready),
    .apb_ext_paddr(apb_apb_ext_if.paddr), .apb_ext_psel(apb_apb_ext_if.psel), .apb_ext_penable(apb_apb_ext_if.penable),
    .apb_ext_pwrite(apb_apb_ext_if.pwrite), .apb_ext_pwdata(apb_apb_ext_if.pwdata), .apb_ext_pstrb(apb_apb_ext_if.pstrb),
    .apb_ext_pprot(apb_apb_ext_if.pprot), .apb_ext_prdata(apb_apb_ext_if.prdata), .apb_ext_pready(apb_apb_ext_if.pready),
    .apb_ext_pslverr(apb_apb_ext_if.pslverr),
    .venc_cfg_paddr(apb_venc_cfg_if.paddr), .venc_cfg_psel(apb_venc_cfg_if.psel), .venc_cfg_penable(apb_venc_cfg_if.penable),
    .venc_cfg_pwrite(apb_venc_cfg_if.pwrite), .venc_cfg_pwdata(apb_venc_cfg_if.pwdata), .venc_cfg_pstrb(apb_venc_cfg_if.pstrb),
    .venc_cfg_pprot(apb_venc_cfg_if.pprot), .venc_cfg_prdata(apb_venc_cfg_if.prdata), .venc_cfg_pready(apb_venc_cfg_if.pready),
    .venc_cfg_pslverr(apb_venc_cfg_if.pslverr),
    .jpeg_cfg_paddr(apb_jpeg_cfg_if.paddr), .jpeg_cfg_psel(apb_jpeg_cfg_if.psel), .jpeg_cfg_penable(apb_jpeg_cfg_if.penable),
    .jpeg_cfg_pwrite(apb_jpeg_cfg_if.pwrite), .jpeg_cfg_pwdata(apb_jpeg_cfg_if.pwdata), .jpeg_cfg_pstrb(apb_jpeg_cfg_if.pstrb),
    .jpeg_cfg_pprot(apb_jpeg_cfg_if.pprot), .jpeg_cfg_prdata(apb_jpeg_cfg_if.prdata), .jpeg_cfg_pready(apb_jpeg_cfg_if.pready),
    .jpeg_cfg_pslverr(apb_jpeg_cfg_if.pslverr),
    .npu_cfg_paddr(apb_npu_cfg_if.paddr), .npu_cfg_psel(apb_npu_cfg_if.psel), .npu_cfg_penable(apb_npu_cfg_if.penable),
    .npu_cfg_pwrite(apb_npu_cfg_if.pwrite), .npu_cfg_pwdata(apb_npu_cfg_if.pwdata), .npu_cfg_pstrb(apb_npu_cfg_if.pstrb),
    .npu_cfg_pprot(apb_npu_cfg_if.pprot), .npu_cfg_prdata(apb_npu_cfg_if.prdata), .npu_cfg_pready(apb_npu_cfg_if.pready),
    .npu_cfg_pslverr(apb_npu_cfg_if.pslverr),
    .irq(apb_irq)
  );
  apb_sva #(.NAME("apb_apb_ext")) u_apb_apb_ext_sva (apb_apb_ext_if);
  initial uvm_config_db#(virtual apb_if)::set(null, "uvm_test_top.env.apb_apb_ext.*", "vif", apb_apb_ext_if);
  apb_sva #(.NAME("apb_venc_cfg")) u_apb_venc_cfg_sva (apb_venc_cfg_if);
  initial uvm_config_db#(virtual apb_if)::set(null, "uvm_test_top.env.apb_venc_cfg.*", "vif", apb_venc_cfg_if);
  apb_sva #(.NAME("apb_jpeg_cfg")) u_apb_jpeg_cfg_sva (apb_jpeg_cfg_if);
  initial uvm_config_db#(virtual apb_if)::set(null, "uvm_test_top.env.apb_jpeg_cfg.*", "vif", apb_jpeg_cfg_if);
  apb_sva #(.NAME("apb_npu_cfg")) u_apb_npu_cfg_sva (apb_npu_cfg_if);
  initial uvm_config_db#(virtual apb_if)::set(null, "uvm_test_top.env.apb_npu_cfg.*", "vif", apb_npu_cfg_if);

  initial begin
    if ($test$plusargs("VCD")) begin
      $dumpfile("ipcam_soc.vcd");
      $dumpvars(0, ipcam_soc_tb_top);
    end
    run_test();
  end
endmodule
